async function shot(name){if(pageScriptEnabled){await page.evaluate(()=>Promise.race([document.fonts.ready,new Promise(r=>setTimeout(r,3000))]));await page.evaluate(()=>Promise.race([new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r))),new Promise(r=>setTimeout(r,1000))]));}const file=String(++n).padStart(2,'0')+'-'+name+'.png',m=await layout();await page.screenshot({path:path.join(dir,file),animations:'allow'});screens.push({file:'extra/'+file,name,metrics:m,synthetic:true,realDataMutation:false});check('overflow.'+name,m.document.width<=m.viewport.width);for(const modal of m.modals){check('modal-bounds.'+name+'.'+modal.class,modal.box.x>=0&&modal.box.y>=0&&modal.box.right<=m.viewport.width+1&&modal.box.bottom<=m.viewport.height+1,modal);if(modal.footer&&modal.body)check('footer-separation.'+name,modal.body.bottom<=modal.footer.top+1,{body:modal.body,footer:modal.footer});}return m}
